import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.D_V8FuNN.js";var i=JSON.parse(`{"title":"Text Field","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/field-types/text.md","filePath":"documentation/field-types/text.md","lastUpdated":1760012816000}`),a={name:`documentation/field-types/text.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="text-field" tabindex="-1">Text Field <a class="header-anchor" href="#text-field" aria-label="Permalink to “Text Field”">​</a></h1><p>Text fields are the most commonly used field type for single-line text input in web forms. They handle plain text data and provide various configuration options for optimal form filling behavior.</p><img src="/assets/image-3.VFE-xGBX.png" alt="text" height="300" width="300"><h2 id="basic-configuration" tabindex="-1">Basic Configuration <a class="header-anchor" href="#basic-configuration" aria-label="Permalink to “Basic Configuration”">​</a></h2><h3 id="field-properties" tabindex="-1">Field Properties <a class="header-anchor" href="#field-properties" aria-label="Permalink to “Field Properties”">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Field Name</strong></td><td>Unique identifier for the field</td><td><code>firstName</code>, <code>email</code>, <code>phone</code></td></tr><tr><td><strong>Field Type</strong></td><td>Set to <strong>Text</strong> for text input fields</td><td><code>Text</code></td></tr><tr><td><strong>Field Selector Type</strong></td><td>Method to locate the field element</td><td><code>Selector</code>, <code>Id</code>, <code>XPath</code></td></tr><tr><td><strong>Field Selector Query</strong></td><td>Unique address to locate the field</td><td><code>#firstName</code>, <code>input[name=&quot;email&quot;]</code></td></tr><tr><td><strong>Field Value</strong></td><td>Data source for field content</td><td>Excel column or default value</td></tr></tbody></table><h2 id="text-field-settings" tabindex="-1">Text Field Settings <a class="header-anchor" href="#text-field-settings" aria-label="Permalink to “Text Field Settings”">​</a></h2><h3 id="simulate-human-typing-speed" tabindex="-1">⌨️ Simulate Human Typing Speed <a class="header-anchor" href="#simulate-human-typing-speed" aria-label="Permalink to “⌨️ Simulate Human Typing Speed”">​</a></h3><p>Enable human-like typing behavior to simulate realistic user input patterns.</p><p><strong>Configuration:</strong></p><ul><li><strong>Toggle Switch</strong>: &quot;Simulate Human Typing Speed&quot; (formerly &quot;Fill the values like a typing tutor&quot;)</li><li><strong>Typing Time</strong>: Set delay in milliseconds between keystrokes <ul><li>Default: <code>100</code> milliseconds</li><li>Range: <code>50</code> - <code>2000</code> milliseconds</li><li>Higher values = slower typing</li></ul></li></ul><hr><h3 id="before-filling-the-value-in-the-field-clear-the-value-of-the-field" tabindex="-1">🧹 Before filling the value in the field, clear the value of the field <a class="header-anchor" href="#before-filling-the-value-in-the-field-clear-the-value-of-the-field" aria-label="Permalink to “🧹 Before filling the value in the field, clear the value of the field”">​</a></h3><p>Automatically clears existing field values before entering new data.</p><p><strong>Configuration:</strong></p><ul><li><strong>Toggle Switch</strong>: Enable/disable field clearing</li><li><strong>Empty Value Field</strong>: Specify what to fill when Excel data is not found</li></ul><hr><h3 id="if-excel-column-value-is-empty-then-fill-this-default-value" tabindex="-1">📋 If excel column value is empty then fill this default value <a class="header-anchor" href="#if-excel-column-value-is-empty-then-fill-this-default-value" aria-label="Permalink to “📋 If excel column value is empty then fill this default value”">​</a></h3><p>Set fallback values when Excel column data is not available.</p><p><strong>Configuration:</strong></p><ul><li><strong>Toggle Switch</strong>: &quot;If excel column value is empty then fill this default value&quot;</li><li><strong>Default Value Input</strong>: Enter the fallback value to use</li><li><strong>Placeholder</strong>: &quot;Enter Field Default Value If Excel Data Not Found&quot;</li></ul><p id="example-scenarios"><strong>Example Scenarios:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Excel Column Value: &quot;John Doe&quot; → Field gets &quot;John Doe&quot;</span></span>
<span class="line"><span>Excel Column Value: &quot;&quot; (empty) → Field gets default value</span></span>
<span class="line"><span>Excel Column Value: null → Field gets default value</span></span></code></pre></div><hr><h3 id="element-detection-settings" tabindex="-1">⏳ Element Detection Settings <a class="header-anchor" href="#element-detection-settings" aria-label="Permalink to “⏳ Element Detection Settings”">​</a></h3><p>Configure how the extension waits for and interacts with form elements.</p><h4 id="wait-until-element-is-found-in-the-page" tabindex="-1">Wait until element is found in the page <a class="header-anchor" href="#wait-until-element-is-found-in-the-page" aria-label="Permalink to “Wait until element is found in the page”">​</a></h4><ul><li><strong>Purpose</strong>: Ensures element exists in DOM before interaction</li><li><strong>Use Case</strong>: Dynamic content, AJAX-loaded elements</li><li><strong>Configuration</strong>: Toggle ON/OFF</li></ul><h4 id="wait-until-element-is-visible-in-the-page" tabindex="-1">Wait until element is visible in the page <a class="header-anchor" href="#wait-until-element-is-visible-in-the-page" aria-label="Permalink to “Wait until element is visible in the page”">​</a></h4><ul><li><strong>Purpose</strong>: Ensures element is both found and visible</li><li><strong>Use Case</strong>: Hidden elements, CSS visibility controls</li><li><strong>Configuration</strong>: Toggle ON/OFF</li></ul><h3 id="javascript-event-triggering" tabindex="-1">⚡ Trigger Javascript Event <a class="header-anchor" href="#javascript-event-triggering" aria-label="Permalink to “⚡ Trigger Javascript Event”">​</a></h3><p>Configure JavaScript events to be triggered on the field element.</p><p><strong>Supported Events:</strong></p><ul><li><strong>change</strong> - Triggers when field value changes</li><li><strong>focus</strong> - Triggers when field receives focus</li><li><strong>blur</strong> - Triggers when field loses focus</li><li><strong>input</strong> - Triggers on every character input</li><li><strong>keydown</strong> - Triggers on key press</li><li><strong>keyup</strong> - Triggers on key release</li></ul><h3 id="text-editor-mode" tabindex="-1">✍️ Text editor mode <a class="header-anchor" href="#text-editor-mode" aria-label="Permalink to “✍️ Text editor mode”">​</a></h3><p>Enable text editor mode for enhanced rich text or custom editor text input handling with natural human typing speed simulation.</p><p><strong>Configuration:</strong></p><ul><li><strong>Text editor mode</strong>: Toggle ON/OFF to enable text editor mode.</li></ul><h4 id="⚙️-settings-when-enabled" tabindex="-1">⚙️ Settings (when enabled): <a class="header-anchor" href="#⚙️-settings-when-enabled" aria-label="Permalink to “⚙️ Settings (when enabled):”">​</a></h4><ul><li><strong>Min Key Delay (ms)</strong>: Minimum delay in milliseconds between key presses (e.g., <code>50</code> ms)</li><li><strong>Max Key Delay (ms)</strong>: Maximum delay in milliseconds between key presses (e.g., <code>120</code> ms)</li><li><strong>Enable Random Pause</strong>: Toggle ON/OFF to simulate natural typing pauses <ul><li><strong>Pause Chance (0 to 1)</strong>: Probability of inserting a pause between keystrokes (e.g., <code>0.2</code>)</li><li><strong>Pause Min (ms)</strong>: Minimum pause duration in milliseconds (e.g., <code>300</code> ms)</li><li><strong>Pause Max (ms)</strong>: Maximum pause duration in milliseconds (e.g., <code>600</code> ms)</li></ul></li><li><strong>Human Typing</strong>: Toggle ON/OFF to enable human typing variations</li></ul><hr><h3 id="if-form-is-aspx-remove-the-input-behavior" tabindex="-1">🔧 If form is ASPX, remove the input behavior <a class="header-anchor" href="#if-form-is-aspx-remove-the-input-behavior" aria-label="Permalink to “🔧 If form is ASPX, remove the input behavior”">​</a></h3><p>Special handling for ASPX (Active Server Pages Extended) forms.</p><p><strong>Configuration:</strong></p><ul><li><strong>Toggle Switch</strong>: &quot;If form is ASPX, remove the input behavior&quot;</li><li><strong>Purpose</strong>: Modifies input behavior specifically for ASPX forms</li><li><strong>Use Case</strong>: Compatibility with Microsoft ASP.NET web applications</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="field-not-filling" tabindex="-1">Field Not Filling <a class="header-anchor" href="#field-not-filling" aria-label="Permalink to “Field Not Filling”">​</a></h3><ul><li>Check selector accuracy</li><li>Verify element visibility</li><li>Test with different selectors</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><a href="/documentation/form-fields/field-types.html">Field Types</a> - Learn about different field types</li><li><a href="/documentation/form-fields/field-response-action.html">Field Response Actions</a> - Configure response behaviors</li><li><a href="/documentation/variable.html">Variables</a> - Use variables in field settings</li><li><a href="/documentation/site/site-settings.html">Site Settings</a> - Configure site-wide settings</li></ul>`,50)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};